+/// Three square bores side by side (half-width 8, centres 30 mm apart).
+fn three_bores() -> Region {
+    let sq = |cx: f64| {
+        let h = 8.0;
+        let pts = vec![Point2::new(cx - h, -h), Point2::new(cx + h, -h), Point2::new(cx + h, h), Point2::new(cx - h, h)];
